INSERT INTO public.exam_config (class, is_open, total_questions, time_limit_minutes, passing_score, max_attempts, show_results_to_students)
INSERT INTO public.questions (class, subject_tag, difficulty, question_text, option_a, option_b, option_c, option_d, correct_option)
VALUES
  (7, 'Keyboard Shortcuts', 'easy', 'Which shortcut quickly SAVES the document or drawing you are working on?', 'Ctrl + O', 'Ctrl + S', 'Ctrl + P', 'Ctrl + N', 'b'),
  (7, 'Keyboard Shortcuts', 'easy', 'Which key moves your typing cursor to the NEXT LINE when writing a paragraph?', 'Backspace', 'Ctrl', 'Spacebar', 'Enter', 'd'),
  (7, 'Keyboard Shortcuts', 'easy', 'Which longest key on the bottom row of a keyboard adds a blank space between words?', 'Alt key', 'Spacebar', 'Enter key', 'Shift key', 'b'),
  (7, 'Keyboard Shortcuts', 'easy', 'Which shortcut selects EVERYTHING on the page or inside a folder at once?', 'Ctrl + A', 'Ctrl + S', 'Ctrl + L', 'Ctrl + E', 'a'),
  (7, 'Keyboard Shortcuts', 'easy', 'Which shortcut CUTS (moves) selected text so you can paste it somewhere else?', 'Ctrl + K', 'Ctrl + C', 'Ctrl + X', 'Ctrl + M', 'c'),
  (7, 'Keyboard Shortcuts', 'easy', 'While watching a video on YouTube or VLC, pressing the Spacebar usually does what?', 'Prints the screen', 'Pauses or plays the video', 'Deletes the video', 'Shuts down the computer', 'b'),
  (7, 'Keyboard Shortcuts', 'easy', 'Which shortcut opens the PRINT box to print a page or save it as a PDF?', 'Ctrl + P', 'Ctrl + F', 'Ctrl + I', 'Ctrl + R', 'a'),
  (7, 'Keyboard Shortcuts', 'medium', 'In Word or Google Docs, what does pressing Ctrl + B do to selected text?', 'Makes the text Bold (thicker)', 'Turns the text Blue', 'Deletes the text', 'Moves text to the bottom', 'a'),
  (7, 'Keyboard Shortcuts', 'medium', 'In a document editor, which shortcut makes selected text Italic (slanted)?', 'Ctrl + I', 'Ctrl + U', 'Ctrl + T', 'Ctrl + L', 'a'),
  (7, 'Keyboard Shortcuts', 'medium', 'In a document editor, which shortcut UNDERLINES the selected words?', 'Ctrl + D', 'Ctrl + O', 'Ctrl + N', 'Ctrl + U', 'd'),
  (7, 'Keyboard Shortcuts', 'medium', 'What is the difference between the Backspace key and the Delete key while typing?', 'Backspace closes the program', 'Delete only works on images', 'Backspace erases to the left of the cursor; Delete erases to the right of the cursor', 'Both do the exact same thing', 'c'),
  (7, 'Keyboard Shortcuts', 'medium', 'If you want to quickly FIND a specific word on a long webpage or PDF, which shortcut do you press?', 'Ctrl + G', 'Ctrl + H', 'Ctrl + Q', 'Ctrl + F', 'd'),
  (7, 'Keyboard Shortcuts', 'medium', 'Which key at the top-left of the keyboard is commonly pressed to cancel a pop-up or exit full-screen video?', 'Insert', 'Tab', 'Esc (Escape)', 'Num Lock', 'c'),
  (7, 'Keyboard Shortcuts', 'medium', 'Which function key is the classic shortcut to REFRESH or reload a webpage in a browser?', 'F12', 'F2', 'F1', 'F5', 'd'),
  (7, 'Keyboard Shortcuts', 'hard', 'If you pressed Ctrl + Z (Undo) by mistake and want your change back, which shortcut performs REDO?', 'Ctrl + Y', 'Ctrl + W', 'Ctrl + E', 'Ctrl + R', 'a'),
  (7, 'Keyboard Shortcuts', 'hard', 'Which keyboard shortcut lets you quickly switch between open apps/windows on Windows?', 'Ctrl + C', 'Alt + Tab', 'Shift + Enter', 'Ctrl + P', 'b'),
  (7, 'Keyboard Shortcuts', 'hard', 'To type a single capital letter or the "@" symbol above the number 2 without turning on Caps Lock, which key do you hold?', 'Ctrl', 'Alt', 'Tab', 'Shift', 'd'),
  (7, 'Keyboard Shortcuts', 'hard', 'Which shortcut opens a brand-new blank document or window in most apps?', 'Ctrl + M', 'Ctrl + D', 'Ctrl + N', 'Ctrl + B', 'c'),
  (7, 'Computer Hardware', 'easy', 'What is the small wheel between the left and right buttons of a mouse used for?', 'Typing numbers', 'Charging the mouse', 'Turning off the monitor', 'Scrolling up and down long pages', 'd'),
  (7, 'Computer Hardware', 'easy', 'Which machine puts your digital document or photo onto a real sheet of paper?', 'Webcam', 'Microphone', 'Printer', 'Scanner', 'c'),
  (7, 'Computer Hardware', 'easy', 'During an online video class, which hardware captures your live face so others can see you?', 'Printer', 'UPS', 'Pendrive', 'Webcam (Camera)', 'd'),
  (7, 'Computer Hardware', 'easy', 'During a voice call or recording, which part captures your voice into the computer?', 'Monitor', 'Speaker', 'Microphone (Mic)', 'Projector', 'c'),
  (7, 'Computer Hardware', 'easy', 'Which pocket-sized device plugs into a USB port to carry files between home and school?', 'Cooling Fan', 'Mouse Pad', 'USB Pendrive (Flash Drive)', 'UPS Battery', 'c'),
  (7, 'Computer Hardware', 'easy', 'On a laptop, what is the flat touch-sensitive rectangle below the keyboard that works like a mouse?', 'Touchpad (Trackpad)', 'Speaker Grill', 'Motherboard', 'Hard Disk', 'a'),
  (7, 'Computer Hardware', 'easy', 'Pressing the RIGHT button on a computer mouse usually opens what?', 'A small shortcut/context menu with helpful options', 'The DVD tray', 'Computer shutdown screen', 'Nothing at all', 'a'),
  (7, 'Computer Hardware', 'medium', 'Which classroom device shines your computer screen onto a large white wall or board so the whole class can watch?', 'Projector', 'Scanner', 'RAM stick', 'Router', 'a'),
  (7, 'Computer Hardware', 'medium', 'On a smartphone or tablet, the screen both shows pictures AND senses your finger taps. What is it called?', 'Joystick', 'Barcode Reader', 'Touchscreen', 'Plotter', 'c'),
  (7, 'Computer Hardware', 'medium', 'What Does "Hardware" mean in simple everyday words?', 'Secret passwords', 'Websites on the internet', 'The physical parts of a computer that you can actually see and touch', 'Only paid mobile games', 'c'),
  (7, 'Computer Hardware', 'medium', 'In Indian homes and school labs, a small box called a UPS is connected to desktop PCs. Why is it useful?', 'It provides short battery backup during a power cut so you can save your work safely', 'It prints color photos', 'It cleans computer viruses', 'It makes games run faster', 'a'),
  (7, 'Computer Hardware', 'medium', 'What is the opposite of a Printer — a device that turns a paper certificate or drawing into a digital image file on your PC?', 'Projector', 'Speaker', 'Scanner', 'Modem', 'c'),
  (7, 'Computer Hardware', 'medium', 'Which single modern cable carries BOTH sharp high-definition video AND audio from a laptop to a TV or projector?', 'Earphone jack', 'Power cord', 'HDMI cable', 'Mouse wire', 'c'),
  (7, 'Computer Hardware', 'medium', 'At a supermarket checkout or school library, which handheld device reads black-and-white striped labels instantly?', 'Barcode Scanner', 'Joystick', 'Cooling Pad', 'Microphone', 'a'),
  (7, 'Computer Hardware', 'hard', 'Why can a laptop keep running during a power cut even without an external UPS?', 'Laptops do not use electricity', 'Laptops have a built-in rechargeable battery inside', 'Laptops run on Wi-Fi waves', 'The keyboard generates power', 'b'),
  (7, 'Computer Hardware', 'hard', 'What is the tiny removable storage card used inside many cameras and Android phones called?', 'MicroSD (Memory) card', 'SIM card', 'Graphics card', 'Credit card', 'a'),
  (7, 'Computer Hardware', 'hard', 'What is the main job of the small spinning fan inside a laptop or desktop cabinet?', 'To make music louder', 'To boost Wi-Fi signal', 'To blow dust onto the screen', 'To keep the processor and internal parts cool so the computer does not overheat', 'd'),
  (7, 'Computer Hardware', 'hard', 'In everyday phones and computers, what is the simple difference between RAM and Storage (SSD/ROM)?', 'RAM is only for printers', 'Both are names for the screen', 'RAM stores photos forever; Storage deletes everything on restart', 'RAM holds active apps temporarily while working; Storage keeps your photos and files saved even when powered off', 'd'),
  (7, 'Application Software & OS', 'easy', 'Which application is best for making visual slideshows to present a project in front of your class?', 'Alarm Clock', 'Recycle Bin', 'Notepad', 'PowerPoint or Google Slides', 'd'),
  (7, 'Application Software & OS', 'easy', 'What do we call the main welcome screen with icons and wallpaper that appears after logging in to a PC?', 'BIOS', 'Spreadsheet', 'Inbox', 'Desktop', 'd'),
  (7, 'Application Software & OS', 'easy', 'Which popular free media player with an orange traffic-cone icon plays almost any video or audio file?', 'Notepad', 'VLC Media Player', 'MS Paint', 'Sticky Notes', 'b'),
  (7, 'Application Software & OS', 'easy', 'On an Android smartphone, which official app store is used to safely install apps?', 'Paint 3D', 'Recycle Bin', 'Google Play Store', 'File Explorer', 'c'),
  (7, 'Application Software & OS', 'easy', 'Look at the file name "annual_day_photo.jpg". What kind of file is it?', 'A picture / image file', 'A spreadsheet table', 'A computer virus', 'A music song only', 'a'),
  (7, 'Application Software & OS', 'easy', 'Look at the file name "school_anthem.mp3". What kind of file is it?', 'An audio / music file', 'A printable PDF circular', 'A folder', 'A website browser', 'a'),
  (7, 'Application Software & OS', 'easy', 'Look at the file name "science_fair_demo.mp4". What kind of file is it?', 'A plain text note', 'A video file', 'A font style', 'An empty folder', 'b'),
  (7, 'Application Software & OS', 'medium', 'What are the three small buttons ( — , □ , ✕ ) at the top-right corner of almost every Windows app window for?', 'Mute, Play, and Pause music', 'Print, Save, and Delete', 'Minimize, Maximize, and Close the window', 'Copy, Cut, and Paste text', 'c'),
  (7, 'Application Software & OS', 'medium', 'Which popular design app/website lets students easily create posters, certificates, and invitations using ready templates?', 'Device Manager', 'Disk Cleanup', 'Command Prompt', 'Canva', 'd'),
  (7, 'Application Software & OS', 'medium', 'What does "Software" mean in simple everyday language?', 'The apps, programs, and operating system that run inside a computer or phone', 'The plastic keyboard keys', 'The power socket on the wall', 'Soft cloth used to clean a monitor', 'a'),
  (7, 'Application Software & OS', 'medium', 'Which of the following is an Operating System (the core system software that runs a PC or phone)?', 'Canva', 'Windows 11 / Android', 'YouTube', 'WhatsApp', 'b'),
  (7, 'Application Software & OS', 'medium', 'Why do schools send circulars and admit cards as a ".pdf" file instead of an editable Word file?', 'PDFs do not take even 1 byte of space', 'PDFs only open at night', 'PDFs keep the exact layout, fonts, and alignment looking identical on every phone and computer', 'PDFs automatically translate into 50 languages', 'c'),
  (7, 'Application Software & OS', 'medium', 'Which application is best suited for keeping an attendance list, marks table, or club budget with automatic totals?', 'Microsoft Excel or Google Sheets', 'Sound Recorder', 'Photos viewer', 'MS Paint', 'a'),
  (7, 'Application Software & OS', 'medium', 'What is the difference between "Copy & Paste" and "Cut & Paste" on a file?', 'Copy leaves the original file in place and makes a duplicate; Cut moves the file to the new folder', 'Cut deletes the file permanently', 'Copy works only on photos', 'There is no difference', 'a'),
  (7, 'Application Software & OS', 'hard', 'What is a ".zip" file commonly used for when sharing a project?', 'Making music play faster', 'Bundling many files/folders together into one smaller compressed file for easy sending', 'Changing desktop wallpaper', 'Charging laptop battery faster', 'b'),
  (7, 'Application Software & OS', 'hard', 'In Word or Google Docs, what is the difference between "Save" and "Save As"?', '"Save" only works offline', 'Both print the document on paper', '"Save" updates the current file; "Save As" lets you save a separate copy with a new name or location', '"Save As" deletes the old file', 'c'),
  (7, 'Application Software & OS', 'hard', 'Which long bar at the bottom of a Windows screen shows the Start button, pinned apps, and clock?', 'Bookmark bar', 'Formula bar', 'Scroll bar', 'Taskbar', 'd'),
  (7, 'Application Software & OS', 'hard', 'Why do many students turn on "Dark Mode" in apps when reading or working in the evening?', 'It makes Wi-Fi twice as fast', 'It doubles storage space', 'It prints pages in black paper', 'It uses a dark background that feels gentler on the eyes in low light', 'd'),
  (7, 'Web Browsing & Internet', 'easy', 'If you find a super useful study website and want to save it inside your browser for one-click access tomorrow, you add a:', 'Screen saver', 'Firewall', 'Virus scan', 'Bookmark (Star ★ icon)', 'd'),
  (7, 'Web Browsing & Internet', 'easy', 'When your mouse pointer turns from an arrow into a little pointing HAND over colored/underlined text on a webpage, it means:', 'The computer is frozen', 'It is a clickable link (hyperlink) to another page or file', 'Your mouse is broken', 'You cannot click there', 'b'),
  (7, 'Web Browsing & Internet', 'easy', 'Where do files you download from Chrome or Edge normally get saved on your computer by default?', 'The Clock app', 'The Recycle Bin', 'The "Downloads" folder', 'The Fonts folder', 'c'),
  (7, 'Web Browsing & Internet', 'easy', 'In an email app like Gmail, what does the small PAPERCLIP (📎) button let you do?', 'Attach a file, photo, or PDF to send along with your email', 'Change your password', 'Log out immediately', 'Delete your email account', 'a'),
  (7, 'Web Browsing & Internet', 'easy', 'What is the website address typed at the top of a browser (like `https://mapleskhatauli.com`) commonly called?', 'URL (Website Address)', 'PIN code', 'RAM address', 'Battery level', 'a'),
  (7, 'Web Browsing & Internet', 'easy', 'What does the Left Arrow (←) "Back" button at the top-left of a browser do?', 'Erases a typed letter', 'Takes you back to the previous webpage you were just viewing', 'Closes Windows', 'Rewinds YouTube by 1 hour', 'b'),
  (7, 'Web Browsing & Internet', 'easy', 'Look at an email address: `student@mapleskhatauli.com`. Which symbol always separates the username from the domain name?', '$ (Dollar)', '& (And)', '@ (At symbol)', '# (Hash)', 'c'),
  (7, 'Web Browsing & Internet', 'medium', 'What is that square black-and-white patterned box on posters or ID cards that opens a link when scanned with a phone camera?', 'Emoji', 'SIM Card', 'CPU Chip', 'QR Code', 'd'),
  (7, 'Web Browsing & Internet', 'medium', 'Which of these is ALSO a popular web browser besides Google Chrome?', 'MS Excel', 'Windows Calculator', 'Adobe Photoshop', 'Mozilla Firefox / Microsoft Edge / Apple Safari', 'd'),
  (7, 'Web Browsing & Internet', 'medium', 'If you visited a helpful website yesterday and forgot its name, which browser list helps you find it again?', 'Printer Queue', 'Browsing History (Ctrl + H)', 'Calculator History', 'Bluetooth Devices', 'b'),
  (7, 'Web Browsing & Internet', 'medium', 'What is the real difference between Google Chrome and Google Search?', 'There is zero difference', 'Chrome is a search website; Google is a laptop brand', 'Chrome is the Browser app installed on your device; Google Search is a website used inside a browser to look up info', 'Both are hardware parts', 'c'),
  (7, 'Web Browsing & Internet', 'medium', 'When you see `https://` and a padlock icon in the browser address bar before logging in, what does the "s" in `https` mean?', 'Secure — data between your browser and the website is encrypted so others on Wi-Fi cannot read your password', 'School-only website', 'Screen capture enabled', 'Slow connection', 'a'),
  (7, 'Web Browsing & Internet', 'medium', 'What does opening an "Incognito" or "Private" browser window ACTUALLY do on a shared computer?', 'It stops the browser from saving your browsing history, cookies, and login session on THAT computer after you close the window', 'It makes you completely invisible to websites and your internet provider', 'It gives free unlimited mobile data', 'It blocks all computer viruses automatically', 'a'),
  (7, 'Web Browsing & Internet', 'medium', 'If a webpage shows "404 — Page Not Found", what does that simply mean?', 'Your monitor is broken', 'The specific link or page was moved, deleted, or typed with a spelling mistake', 'Your laptop battery is at 4%', '404 people are viewing the site', 'b'),
  (7, 'Web Browsing & Internet', 'hard', 'When writing a polite email to a teacher or competition organizer, why should you always fill in the "Subject" line?', 'Subject is where you type your password', 'Subject hides your email address', 'So the receiver immediately knows what your email is about before even opening it', 'Emails cannot be sent without 50 words in Subject', 'c'),
  (7, 'Web Browsing & Internet', 'hard', 'If an expected registration confirmation email has not arrived in your Inbox, which email folder should you check next?', 'Downloads folder', 'Recycle Bin on Desktop', 'Drafts folder', 'Spam / Junk folder', 'd'),
  (7, 'Web Browsing & Internet', 'hard', 'Why do websites sometimes ask you to tick "I am not a robot" or pick traffic lights (CAPTCHA)?', 'To test your eyesight for driving', 'To slow down your internet', 'To update your browser', 'To stop automated spam bots from creating fake accounts or flooding forms', 'd'),
  (7, 'Web Browsing & Internet', 'hard', 'In Chrome or Edge, which shortcut opens your recent Downloads list directly inside the browser?', 'Ctrl + U', 'Ctrl + J', 'Ctrl + B', 'Alt + F4', 'b'),
  (7, 'Basic Networking & Connectivity', 'easy', 'What is the box with blinking lights at home or school that shares Wi-Fi internet with phones and computers?', 'Webcam', 'Wi-Fi Router', 'Inkjet Printer', 'Pendrive', 'b'),
  (7, 'Basic Networking & Connectivity', 'easy', 'In a school computer lab, many desktop PCs are plugged into internet wall sockets using a sturdy cable with a clip plug. What is that cable called?', 'Shoe Lace', 'Earphone Wire', 'Ethernet (LAN) Cable', 'HDMI Video Cable', 'c'),
  (7, 'Basic Networking & Connectivity', 'easy', 'On a mobile phone status bar, what do "4G" and "5G" indicate?', 'Generations of mobile cellular network connectivity for internet and calls', 'How many games are installed', 'Battery percentage', 'How many gigabytes of storage are left', 'a'),
  (7, 'Basic Networking & Connectivity', 'easy', 'When you save a PDF circular FROM a school website ONTO your phone, is that called Downloading or Uploading?', 'Downloading', 'Uploading', 'Printing', 'Scanning', 'a'),
  (7, 'Basic Networking & Connectivity', 'easy', 'When you select a photo FROM your computer and post/submit it TO an online portal, is that called Downloading or Uploading?', 'Downloading', 'Uploading', 'Rebooting', 'Formatting', 'b'),
  (7, 'Basic Networking & Connectivity', 'easy', 'Look at the curved fan-shaped icon with 3 or 4 arcs in the corner of your phone or laptop screen. What does it show?', 'Screen brightness', 'CPU temperature', 'Wi-Fi connection and signal strength', 'Speaker volume level', 'c'),
  (7, 'Basic Networking & Connectivity', 'easy', 'Which of these tasks works completely OFFLINE even when you have zero internet connection?', 'Searching on Google', 'Sending an email', 'Streaming a live YouTube video', 'Using the built-in Calculator or typing in Notepad', 'd'),
  (7, 'Basic Networking & Connectivity', 'medium', 'Why do home and school Wi-Fi networks have a password?', 'Because routers cannot turn on without a 20-letter name', 'To make the router light turn blue', 'To charge phones faster', 'So strangers outside cannot use your internet or access devices on your network', 'd'),
  (7, 'Basic Networking & Connectivity', 'medium', 'When a YouTube video pauses with a spinning circle in the middle because the internet is slow, what is that called?', 'Printing', 'Buffering', 'Scanning', 'Zipping', 'b'),
  (7, 'Basic Networking & Connectivity', 'medium', 'Roughly how far does normal Bluetooth (like wireless earbuds connected to your phone) usually reach clearly?', 'Only 1 millimeter', 'Across the entire state (500 km)', 'A short room-size distance (around 10 meters / 30 feet)', 'Around the whole planet', 'c'),
  (7, 'Basic Networking & Connectivity', 'medium', 'Your laptop says "Connected to Wi-Fi, No Internet." What does this message actually mean?', 'Your laptop is connected to the Wi-Fi router in the room, but the router’s outside internet line is down', 'Your screen is damaged', 'You forgot your laptop password', 'Your laptop Wi-Fi card is broken', 'a'),
  (7, 'Basic Networking & Connectivity', 'medium', 'Why are desktop computers in an exam lab often connected by Ethernet (LAN) cables instead of Wi-Fi?', 'A wired Ethernet cable gives steadier, interference-free internet for 30+ PCs at the same time', 'Desktop PCs can never use Wi-Fi', 'LAN cables also power the monitor without electricity', 'Wi-Fi only works on phones', 'a'),
  (7, 'Basic Networking & Connectivity', 'medium', 'Internet plan speeds from providers like JioFiber, Airtel, or BSNL are commonly advertised in "100 Mbps". What does Mbps measure?', 'How many months the plan lasts', 'Megabits per second — how fast data transfers over your internet connection', 'How far the Wi-Fi reaches in meters', 'How many devices are allowed', 'b'),
  (7, 'Basic Networking & Connectivity', 'medium', 'Companies like BSNL, Airtel, Jio, or local fiber broadband providers that connect homes/schools to the internet are called:', 'Search Engines', 'Operating Systems', 'ISPs (Internet Service Providers)', 'Web Browsers', 'c'),
  (7, 'Basic Networking & Connectivity', 'hard', 'Why does Wi-Fi signal become weaker when you walk three rooms away behind thick concrete walls?', 'Gravity pulls Wi-Fi down', 'The phone screen gets smaller', 'Wi-Fi needs sunlight to travel', 'Thick walls and distance absorb and weaken wireless radio waves from the router', 'd'),
  (7, 'Basic Networking & Connectivity', 'hard', 'What is a "Local Area Network (LAN)" in simple everyday words?', 'Satellites orbiting Mars', 'A type of USB pendrive', 'An antivirus program', 'Computers, laptops, and printers connected together inside one building, home, or school campus', 'd'),
  (7, 'Basic Networking & Connectivity', 'hard', 'If ONE Wi-Fi printer is connected to the school office Wi-Fi router, how many computers on that same Wi-Fi can print to it?', 'Only a computer plugged into it with an HDMI cable', 'All authorized computers/phones on that same Wi-Fi network can share and print to it wirelessly', 'Zero — Wi-Fi printers cannot print', 'Only phones with no SIM card', 'b'),
  (7, 'Basic Networking & Connectivity', 'hard', 'When you mirror your phone or laptop screen wirelessly onto a classroom Smart TV without any cable, what is that feature called?', 'Incognito Browsing', 'Disk Formatting', 'Screen Casting / Screen Mirroring', 'Zipping', 'c'),
  (7, 'Social Ethics & Cyber Safety', 'easy', 'In online group chats or comments, typing an entire message IN ALL CAPITAL LETTERS LIKE THIS is usually read as:', 'Encrypting the message', 'Whispering politely', 'SHOUTING or being rude online', 'Writing faster', 'c'),
  (7, 'Social Ethics & Cyber Safety', 'easy', 'If a junior student asks a very basic computer question in the tech club, how should a good member respond?', 'Explain it patiently and kindly — everyone starts as a beginner!', 'Tell them to quit computers', 'Ignore them completely', 'Laugh at them in front of the group', 'a'),
  (7, 'Social Ethics & Cyber Safety', 'easy', 'If someone repeatedly sends mean, hurtful, or threatening messages to a classmate online, what is that harmful behavior called?', 'Cyberbullying (which must be reported to parents/teachers, never joined!)', 'Cloud Computing', 'Web Browsing', 'Troubleshooting', 'a'),
  (7, 'Social Ethics & Cyber Safety', 'easy', 'You receive a dramatic WhatsApp forward saying "Tomorrow is a sudden holiday — forward to 20 friends!" What is the smart, responsible step?', 'Forward it to 50 groups immediately', 'Do NOT forward blindly — verify first from the official school notice or teacher', 'Skip homework without checking', 'Post it as breaking news', 'b'),
  (7, 'Social Ethics & Cyber Safety', 'easy', 'Why shouldn’t you eat sticky snacks or keep an open cup of water right over a computer keyboard?', 'Water changes the wallpaper', 'Snacks reduce Wi-Fi bars', 'Crumbs and spilled liquid can permanently short-circuit and ruin the keyboard or laptop', 'Food slows down Google Search', 'c'),
  (7, 'Social Ethics & Cyber Safety', 'easy', 'If a pop-up flashes on screen: "🎉 CONGRATULATIONS! You won a free iPhone! Click here & enter your details!", what is it almost certainly?', 'A Windows system update', 'An official CBSE scholarship', 'A real gift from your browser', 'A scam / phishing trap trying to steal personal details or install malware — close it immediately!', 'd'),
  (7, 'Social Ethics & Cyber Safety', 'easy', 'What is "Netiquette"?', 'A brand of Ethernet cable', 'A type of mosquito net', 'An offline calculator game', 'Good manners, kindness, and respectful behavior when communicating on the internet', 'd'),
  (7, 'Social Ethics & Cyber Safety', 'medium', 'Should you share your home address, school timetable, and phone number publicly with unknown strangers in online game chats?', 'Yes, if they have a cool profile picture', 'No — keep personal details private to stay safe online', 'Yes, if they offer free game coins', 'Yes, on every public comment section', 'b'),
  (7, 'Social Ethics & Cyber Safety', 'medium', 'When you use a diagram, photo, or quote created by someone else in your school presentation, what is the honest thing to do?', 'Never use books or references', 'Crop out their name and claim it as yours', 'Give clear credit to the original creator or source instead of pretending you made it yourself', 'Forbid anyone else from seeing the source', 'c'),
  (7, 'Social Ethics & Cyber Safety', 'medium', 'To keep your eyes comfortable while studying or working on a computer, what does the healthy "20-20-20 Rule" recommend?', 'Every 20 minutes, look at something 20 feet away for 20 seconds to relax your eyes', 'Open 20 tabs at brightness 20%', 'Blink only 20 times a day', 'Sit 20 millimeters from the screen for 20 hours', 'a'),
  (7, 'Social Ethics & Cyber Safety', 'medium', 'Important UPI Safety Rule in India: Do you EVER need to enter your secret UPI PIN to RECEIVE money from someone?', 'NEVER! A UPI PIN is ONLY entered when money is GOING OUT from your account — asking you to enter PIN to "receive" money is a scam!', 'Yes, you must enter UPI PIN to receive gifts', 'Yes, scanning any QR code automatically credits money after PIN', 'UPI PIN is just your roll number', 'a'),
  (7, 'Social Ethics & Cyber Safety', 'medium', 'What is "Two-Factor Authentication (2FA)" on email or social accounts, and why is it great?', 'It forces two friends to share one account', 'It adds a second check (like a code on your phone) besides your password, so thieves can’t break in with a leaked password alone', 'It deletes your account after two days', 'It slows down typing speed by half', 'b'),
  (7, 'Social Ethics & Cyber Safety', 'medium', 'Why is reusing the EXACT SAME password across 10 different games, websites, and your main email risky?', 'It uses extra storage on your phone', 'There is zero risk', 'If even one small game site gets hacked, attackers immediately try that same password on your email and other accounts!', 'Browsers block repeated passwords', 'c'),
  (7, 'Social Ethics & Cyber Safety', 'medium', 'How should a responsible student use AI tools (like ChatGPT or Gemini) when working on a project or assignment?', 'Use AI during closed-book tests', 'Trust every single date or quote from AI without checking', 'Copy-paste the entire AI output without reading a word and sign it as 100% your own', 'Use AI to brainstorm, understand tough ideas, or debug — then write/build in your own understanding and honestly mention where AI helped', 'd'),
  (7, 'Social Ethics & Cyber Safety', 'hard', 'You install a simple "Flashlight" app on a phone, and it suddenly asks permission to read your Contacts, Call Logs, and Messages. What should you think?', 'Allow everything without reading', 'Flashlights need your contacts to shine brighter', 'Give it microphone access too', 'Deny/uninstall! A flashlight only needs the camera LED — asking for private contacts and messages is a big privacy red flag', 'd'),
  (7, 'Social Ethics & Cyber Safety', 'hard', 'What is "Phishing"?', 'Testing internet speed', 'Fake emails, SMS, or look-alike websites pretending to be a trusted bank/company to trick you into typing passwords or OTPs', 'Searching for ocean documentaries online', 'Cleaning computer fans', 'b'),
  (7, 'Social Ethics & Cyber Safety', 'hard', 'What does your "Digital Footprint" mean?', 'The size of your laptop in inches', 'Walking barefoot in the computer lab', 'The lasting trail of posts, comments, photos, and public activity associated with you on the internet', 'A fingerprint unlock sensor', 'c'),
  (7, 'Social Ethics & Cyber Safety', 'hard', 'Why is downloading "Cracked / Pirated" paid software or game cheats from shady websites dangerous as well as unethical?', 'Besides disrespecting creators’ work, pirated cracks are one of the #1 ways password-stealing malware infects home PCs!', 'It upgrades your monitor', 'Official free alternatives like VLC, GIMP, or LibreOffice do not exist', 'Cracked software runs faster and safer than official apps', 'a');
